const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const students=[{id:1,name:'Алихан Садыков',hours:2},{id:2,name:'София Ким',hours:7},{id:3,name:'Даниил Петров',hours:4},{id:4,name:'Амина Омарова',hours:5}];let requests=[{id:5,name:'Марк Волков',hours:0},{id:6,name:'Алина Серикова',hours:0}];const studentComments=['Альфа, пн / ср / пт в 19:00','Альфа, пн / ср / пт в 19:00','Альфа, пн / ср / пт в 19:00','Индивидуально, ср / сб в 17:00','Занимаюсь в вечерней группе, пн / ср / пт в 19:00','Утренняя группа, вт / чт в 09:00'];[...students,...requests].forEach((s,i)=>{s.comment=studentComments[i];s.name=s.name.split(' ').reverse().join(' ')});
