function sessionStart(g,d){return new Date(d+'T'+(overrides[sk(g,d)]?.time||g.time)).getTime()}
function canCancel(g,d){return !overrides[sk(g,d)]?.cancel && sessionStart(g,d)-Date.now()>86400000}
function sessionCard(g,d,student=false){let o=overrides[sk(g,d)]||{},time=o.time||g.time;let disabled=new Date(d+'T'+time)-Date.now()<86400000;let cancelled=absent[sk(g,d)+'_1'];let remaining=sessionStart(g,d)-Date.now(),soon=remaining>0&&remaining<=3600000,status=sessionStatus(g,d);return `<div class="card session ${status==='live'?'live':status==='completed'?'completed':soon?'soon':''}"><div class="time">${time}<small>1 час</small></div><div class="body"><span class="badge">${status==='live'?'Тренировка идёт':status==='completed'?'Завершена':soon?'Скоро · через '+Math.ceil(remaining/60000)+' мин':g.type}</span><h3>${esc(g.name)}</h3><div class="meta">${esc(g.place)} · ${g.members.length} уч.</div>${student?'':balanceWarning(g,d)}<div class="actions">${student?`<button ${disabled||cancelled?'disabled':''} onclick="cancelParticipation(${g.id},'${d}')">${cancelled?'Участие отменено':'Не смогу прийти'}</button>${disabled&&!cancelled?'<span class="meta">До начала менее 24 часов</span>':''}`:`<button onclick="openSession(${g.id},'${d}')">Открыть тренировку</button>`}</div></div></div>`}
function coachView(){if(page==='subscription')return subscriptionView();if(page==='groups'&&groupTab==='students'&&!detail)return studentsView();if(page==='home'){let dates=Array.from({length:7},(_,i)=>{let d=new Date(day);d.setDate(d.getDate()+i);return d});let list=sessions(chosen).sort((a,b)=>(sessionStatus(a,chosen)==='completed')-(sessionStatus(b,chosen)==='completed')||sessionStart(a,chosen)-sessionStart(b,chosen));return `<div class="section-title"><h2>Расписание</h2><input aria-label="Дата календаря" type="date" value="${chosen}" style="width:155px" onchange="chosen=this.value;render()"></div><div class="week">${dates.map(d=>`<button class="${key(d)===chosen?'selected':''}" onclick="chosen='${key(d)}';render()"><small>${d.toLocaleDateString('ru',{weekday:'short'})}</small><b>${d.getDate()}</b></button>`).join('')}</div><div class="section-title"><h2>${fmt(chosen)}</h2><span class="meta">${list.length} занятий</span></div>${list.map(g=>sessionCard(g,chosen)).join('')||'<div class="card empty">На этот день тренировок нет</div>'}`}
if(page==='groups'){if(detail)return groupView(groups.find(g=>g.id===detail));return heading('Мои группы','Регулярные занятия и персональные тренировки','<button class="primary" onclick="createGroup()">+ Создать</button>')+groupTabs()+`<label class="list-search">Поиск групп<input type="search" placeholder="Название группы" oninput="filterCards(this.value, '.group-card')"></label><div class="cards">${groups.map(g=>`<div class="card group-card"><div class="group-card-top"><span class="badge">${g.type}</span><details class="group-menu"><summary aria-label="Действия с группой ${esc(g.name)}" title="Действия с группой">⋯</summary><div class="group-menu-items"><button onclick="renameGroup(${g.id})">Переименовать</button><button class="danger-text" onclick="askDeleteGroup(${g.id})">Удалить</button></div></details></div><h2>${esc(g.name)}</h2><p>${esc(g.place)}<br><span class="meta">${esc(g.city||'')} · ${esc(g.address||'')}</span></p><div class="meta">${g.days.map(n=>['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][n]).join(' · ')} · ${g.time}<br>${g.end?'До '+fmt(g.end):'Без даты окончания'}</div><div class="card-foot"><span>${g.members.length} учеников</span><button onclick="detail=${g.id};render()">Открыть →</button></div></div>`).join('')}</div>`}if(page==='requests'){let list=tab==='incoming'?requests:tab==='accepted'?students:rejectedRequests;return heading('Заявки','Принимайте учеников после договорённости об оплате','<button onclick="premiumExport()">↓ Выгрузить отчёт</button>')+`<div class="tabs"><button class="${tab==='incoming'?'active':''}" onclick="tab='incoming';render()">Входящие · ${requests.length}</button><button class="${tab==='accepted'?'active':''}" onclick="tab='accepted';render()">Принятые · ${students.length}</button><button class="${tab==='rejected'?'active':''}" onclick="tab='rejected';render()">Отклонённые · ${rejectedRequests.length}</button></div><div class="card">${list.map(s=>requestPerson(s,tab)).join('')||`<div class="empty">${tab==='rejected'?'Отклонённых заявок пока нет':tab==='accepted'?'Принятых учеников пока нет':'Новых заявок пока нет'}</div>`}</div>`}if(page==='reports')return reportsView();return heading('Профиль','Эту информацию увидят ученики','<button onclick="page=\'reports\';setReportPeriod(\'month\')">Оплаты и выручка</button>')+`<form class="card fields profile" onsubmit="saveProfile(event)"><label>ФИО<input name="name" value="${esc(profile.name)}" required></label>${venueFields(profile)}<label>О себе<textarea name="bio" placeholder="Расскажите, кого и чему вы обучаете, сколько стоят индивидуальные и групповые тренировки">${esc(profile.bio)}</textarea></label><button class="primary">Сохранить</button></form>`}
function commentInfo(s){return `<div class="student-comment">${(s.coachComment??s.comment)?esc(s.coachComment??s.comment):'Комментарий не указан'}</div>`}
function requestPerson(s,status){if(status==='incoming')return person(s,true);return `<div class="person"><div class="avatar">${esc(s.name[0])}</div><div class="info"><strong>${esc(s.name)}</strong>${commentInfo(s)}</div>${status==='accepted'?`<button onclick="toast('Демо: Telegram-чат ученика будет доступен после подключения бота')">Telegram-чат</button>`:'<span class="meta">Отклонена</span>'}</div>`}
function person(s,incoming=false){return `<div class="person"><div class="avatar">${esc(s.name[0])}</div><div class="info"><strong>${esc(s.name)}</strong><div class="meta">${incoming?'Заявка · Астана':groups.find(g=>g.members.includes(s.id))?.name||'Пока без группы'}</div>${incoming?commentInfo(s):''}</div>${incoming?`<button class="primary" onclick="accept(${s.id})">Принять</button><button onclick="reject(${s.id})">Отклонить</button>`:`<span class="balance ${s.hours<=2?'low':''}">${s.hours} ч</span>`}</div>`}function groupView(g){return `<button class="ghost" onclick="detail=null;render()">← Все группы</button>`+heading(esc(g.name),`${g.type} · ${esc(g.place)} · ${esc(g.city||'')} · ${esc(g.address||'')}`)+`<div class="card"><div class="row"><h2>Ученики · ${g.members.length}</h2><button onclick="addMembers(${g.id})">+ Добавить</button></div>${g.members.map(id=>person(students.find(s=>s.id===id))).join('')}</div><div class="card" style="margin-top:18px"><h3>Расписание</h3><p>${g.days.map(n=>['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][n]).join(' · ')} в ${g.time} · 1 час</p><span class="meta">С ${fmt(g.start)}${g.end?' до '+fmt(g.end):' · Без даты окончания'}</span></div>`}
function accept(id){const student=requests.find(s=>s.id===id);if(!student)return;students.push(student);requests=requests.filter(s=>s.id!==id);render();toast('Заявка принята. Ученик доступен в разделе Группы → Ученики')}function reject(id){const request=requests.find(s=>s.id===id);if(!request)return;rejectedRequests.push(request);requests=requests.filter(s=>s.id!==id);render();toast('Заявка отклонена')}const money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'KZT',maximumFractionDigits:2}).format(n);
function editHours(id,approval=false){let s=(approval?requests:students).find(s=>s.id===id);if(!s)return;modal(`<h2>${approval?'Одобрить заявку · ':''}${esc(s.name)}</h2><p>Остаток: ${s.hours} ч</p><form class="fields" onsubmit="event.preventDefault();recordPayment(${id},this,${approval})"><div class="actions"><button type="button" onclick="this.form.elements.hours.value=2">+2 часа</button><button type="button" onclick="this.form.elements.hours.value=5">+5 часов</button></div><div class="payment-fields"><label>Часы *<input name="hours" type="number" min="1" step="1" required></label><label>Оплачено, ₸ *<input name="paid" type="number" min="0" step="0.01" required placeholder="Введите сумму"></label></div><label>Дата оплаты *<input name="paidDate" type="date" value="${key(new Date())}" max="${key(new Date())}" required></label><label>Кто оплатил<input name="payer" value="${esc(s.name)}" required maxlength="120"></label><label>Комментарий тренера<textarea name="comment" maxlength="500" placeholder="Например: Альфа, пн / ср / пт, 19:00">${esc(s.coachComment??s.comment??'')}</textarea></label><div class="actions"><button class="primary">${approval?'Одобрить и сохранить оплату':'Добавить часы и оплату'}</button><button type="button" onclick="closeModal()">Отмена</button></div></form><h3 style="margin-top:24px">История оплат</h3>${payments.filter(p=>p.studentId===id).map(p=>`<div class="payment-entry"><strong>+${p.hours} ч · ${money(p.amountMinor/100)}</strong><div class="meta">${esc(p.paidDate)} · ${esc(p.groupName)} · ${esc(p.groupType)}<br>Плательщик: ${esc(p.payer)}</div></div>`).join('')||'<p>Оплат пока нет</p>'}`)}
function recordPayment(id,form,approval=false){settleSessions();const f=new FormData(form),rawHours=String(f.get('hours')??'').trim(),rawPaid=String(f.get('paid')??'').trim(),hours=Number(rawHours),amount=Number(rawPaid),paidDate=String(f.get('paidDate')),payer=String(f.get('payer')??'').trim();const s=(approval?requests:students).find(s=>s.id===id),g=groups.find(g=>g.members.includes(id));if(!s)return;if(!rawHours||!Number.isSafeInteger(hours)||hours<=0||!Number.isSafeInteger(s.hours+hours))return toast('Укажите положительное целое количество часов');if(!rawPaid||!/^\d+(\.\d{1,2})?$/.test(rawPaid)||!Number.isSafeInteger(Math.round(amount*100))||amount<0)return toast('Укажите оплаченную сумму, не меньше нуля');if(!/^\d{4}-\d{2}-\d{2}$/.test(paidDate)||!Number.isFinite(new Date(paidDate+'T12:00').getTime())||key(new Date(paidDate+'T12:00'))!==paidDate||paidDate>key(new Date())||!payer)return toast('Укажите корректную дату оплаты и плательщика');const entry={id:crypto.randomUUID(),studentId:id,studentName:s.name,payer,groupId:g?.id??null,groupName:g?.name??'Без группы',groupType:g?.type??'Не назначен',hours,amountMinor:Math.round(amount*100),paidDate,recordedAt:new Date().toISOString(),recordedBy:profile.name,comment:String(f.get('comment')||'')};if(approval){students.push(s);requests=requests.filter(r=>r.id!==id)}s.coachComment=String(f.get('comment')||'').trim();payments.unshift(entry);s.hours+=hours;log.unshift({id,paymentId:entry.id,text:`${paidDate} · +${hours} ч · Оплачено ${money(amount)} · ${payer}`});saveDemoState();closeModal();render();toast(approval?'Заявка одобрена. Часы и оплата сохранены':'Часы и оплата сохранены')}
function setReportPeriod(period){const now=new Date();reportFrom=key(new Date(now.getFullYear(),period==='year'?0:now.getMonth(),1));reportTo=key(now);render()}
function filteredPayments(){return payments.filter(p=>(!reportFrom||p.paidDate>=reportFrom)&&(!reportTo||p.paidDate<=reportTo)&&(!reportType||p.groupType===reportType))}
function reportsView(){const list=filteredPayments(),total=list.reduce((sum,p)=>sum+p.amountMinor,0);return heading('Оплаты и выручка','По дате фактической оплаты','<button onclick="page=\'profile\';render()">Назад</button>')+`<div class="card fields"><div class="actions"><button onclick="setReportPeriod('month')">Этот месяц</button><button onclick="setReportPeriod('year')">Этот год</button></div><form class="fields" onsubmit="event.preventDefault();if(this.from.value>this.to.value){toast('Начало периода должно быть раньше окончания');return}reportFrom=this.from.value;reportTo=this.to.value;reportType=this.kind.value;render()"><div class="payment-fields"><label>С<input name="from" type="date" value="${reportFrom}" required></label><label>По<input name="to" type="date" value="${reportTo}" required></label></div><label>Тип группы<select name="kind"><option value="">Все</option ${reportType==='Групповая'?'selected':''}>Групповая</option><option ${reportType==='Индивидуальная'?'selected':''}>Индивидуальная</option><option ${reportType==='Не назначен'?'selected':''}>Не назначен</option></select></label><button>Показать</button></form><h2>Получено: ${money(total/100)}</h2><span class="meta">${list.length} оплат · ${list.reduce((n,p)=>n+p.hours,0)} ч начислено</span></div><div class="card" style="margin-top:20px">${list.map(p=>`<div class="payment-entry"><div class="row"><strong>${esc(p.studentName)}</strong><strong>${money(p.amountMinor/100)}</strong></div><div class="meta">${esc(p.paidDate)} · +${p.hours} ч · ${esc(p.groupName)} · ${esc(p.groupType)}<br>Оплатил: ${esc(p.payer)}<br>Записал: ${esc(p.recordedBy)} · ${new Date(p.recordedAt).toLocaleString('ru-RU')}${p.comment?'<br>'+esc(p.comment):''}</div></div>`).join('')||'<p>За этот период оплат нет. Добавьте часы и сумму оплаты ученику внутри группы.</p>'}</div>`}
function balanceWarning(g,d){const remaining=sessionStart(g,d)-Date.now();if(remaining<=-3600000||remaining>86400000)return '';const zero=g.members.map(id=>students.find(s=>s.id===id)).filter(s=>s&&s.hours<1&&!absent[sk(g,d)+'_'+s.id]);return zero.length?`<div class="balance-warning"><strong>Не хватает часов для тренировки</strong><div>${zero.map(s=>esc(s.name)).join(', ')} — баланс 0 ч. Проверьте оплату и добавьте часы.</div><button onclick="page='groups';groupTab='students';detail=null;render()">К ученикам</button></div>`:''}
function saveDemoState(){try{localStorage.setItem('topcoach-demo-v1',JSON.stringify({students,requests,rejectedRequests,groups,profile,log,payments,overrides,absent,attendance,lifecycleSince,completedSessions}))}catch{}}
function restoreDemoState(){try{const data=JSON.parse(localStorage.getItem('topcoach-demo-v1'));if(!data)return;students.splice(0,students.length,...data.students);requests=data.requests;rejectedRequests=data.rejectedRequests;groups=data.groups;profile=data.profile;log=data.log;payments=data.payments||[];overrides=data.overrides;absent=data.absent;attendance=data.attendance;lifecycleSince=data.lifecycleSince??Date.now();completedSessions=data.completedSessions||{}}catch{}}
function available(){return students.filter(s=>!groups.some(g=>g.members.includes(s.id)))}
function studentPicker(){return available().map(s=>`<label class="student-option"><input name="member" type="checkbox" value="${s.id}"><span><strong>${esc(s.name)}</strong>${commentInfo(s)}</span></label>`).join('')||'<p>Одобренных учеников без группы пока нет. Можно создать группу и добавить их позже.</p>'}
function attachMembers(id,e){e.preventDefault();settleSessions();const g=groups.find(g=>g.id===id),ids=new FormData(e.target).getAll('member').map(Number);if(g.type==='Индивидуальная'&&ids.length+g.members.length>1)return toast('Выберите одного ученика для индивидуальной группы');if(ids.some(id=>!available().some(s=>s.id===id)))return toast('Ученик уже состоит в группе');g.members.push(...ids);closeModal();render();toast('Ученики добавлены')}
function addMembers(id){const g=groups.find(g=>g.id===id);if(g.type==='Индивидуальная'&&g.members.length)return toast('В индивидуальной группе может быть только один ученик');modal(`<h2>Добавить учеников</h2><form onsubmit="attachMembers(${id},event)">${studentPicker()}<div class="actions"><button class="primary" ${available().length?'':'disabled'}>Добавить</button><button type="button" onclick="closeModal()">Отмена</button></div></form>`)}
function venueFields(current={}){const v=venues.find(v=>v.name===current.place&&v.address===current.address);return `<label>Город<select name="city" required onchange="filterVenues(this.form)">${cities.map(c=>`<option value="${c.name}" ${(current.city||'Астана')===c.name?'selected':''}>${c.code} · ${c.name}</option>`).join('')}</select></label><label>Клуб / корт<select name="venue" onchange="selectVenue(this.form)"><option value="">Указать вручную</option>${venues.filter(v=>v.city===(current.city||'Астана')).map(item=>`<option value="${item.id}" ${v?.id===item.id?'selected':''}>${esc(item.name)} — ${esc(item.address)}</option>`).join('')}</select></label><label>Название площадки<input name="place" value="${esc(current.place||'')}" ${v?'readonly':''} required></label><label>Адрес<input name="address" value="${esc(current.address||'')}" ${v?'readonly':''} required></label>`}
function filterVenues(form){form.elements.venue.innerHTML='<option value="">Указать вручную</option>'+venues.filter(v=>v.city.toLowerCase()===form.elements.city.value.trim().toLowerCase()).map(v=>`<option value="${v.id}">${esc(v.name)} — ${esc(v.address)}</option>`).join('');selectVenue(form)}
function selectVenue(form){let v=venues.find(v=>v.id===form.elements.venue.value);for(const [field,value] of [['place',v?.name||''],['address',v?.address||'']]){form.elements[field].value=value;form.elements[field].readOnly=!!v}}
function createGroup(){modal(`<h2>Новая группа</h2><form class="fields" onsubmit="saveGroup(event)"><label>Тип<select name="type"><option>Групповая</option><option>Индивидуальная</option></select></label><label>Название<input name="name" required maxlength="60"></label>${venueFields({city:profile.city})}<label>Время<input name="time" type="time" value="19:00" required></label><div class="days">${[1,2,3,4,5,6,0].map(n=>`<label><input name="days" value="${n}" type="checkbox">${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][n]}</label>`).join('')}</div><label>Начало<input name="start" type="date" value="${today}" required></label><label>Окончание · необязательно<input name="end" type="date" min="${today}"></label><div><h3>Ученики · необязательно</h3>${studentPicker()}</div><div class="actions"><button class="primary">Создать</button><button type="button" onclick="closeModal()">Отмена</button></div></form>`)}
function saveGroup(e){e.preventDefault();let f=new FormData(e.target),days=f.getAll('days').map(Number),members=f.getAll('member').map(Number);if(!days.length)return toast('Выберите дни тренировок');if(f.get('end')&&f.get('end')<f.get('start'))return toast('Дата окончания должна быть после начала');if(f.get('type')==='Индивидуальная'&&members.length>1)return toast('В индивидуальной группе может быть только один ученик');if(members.some(id=>!available().some(s=>s.id===id)))return toast('Выберите одобренных учеников без группы');groups.push({id:Date.now(),name:f.get('name'),type:f.get('type'),city:f.get('city'),cityId:cities.find(c=>c.name===f.get('city'))?.id,cityCode:cities.find(c=>c.name===f.get('city'))?.code,venueId:f.get('venue')||null,address:f.get('address'),place:f.get('place'),time:f.get('time'),days,start:f.get('start'),end:f.get('end'),members});closeModal();render();toast('Группа создана')}
function saveProfile(e){e.preventDefault();profile=Object.fromEntries(new FormData(e.target));const city=cities.find(c=>c.name===profile.city);profile.cityId=city?.id;profile.cityCode=city?.code;render();toast('Профиль сохранён')}
function setPresence(id,d,studentId,present,input){const g=groups.find(g=>g.id===id);if(sessionStatus(g,d)==='completed')return toast('Тренировка завершена');const k=id+'_'+d+'_'+studentId;attendance[k]=present;absent[k]=!present;saveDemoState();if(input)input.closest('label').querySelector('.presence-label').textContent=present?'Присутствует':'Отсутствует';else openSession(id,d)}
function openSession(id,d){let g=groups.find(g=>g.id===id),k=sk(g,d);modal(`<h2>${esc(g.name)} · ${fmt(d)}</h2><p>Присутствует — спишется 1 час после занятия. Отсутствует — часы сохранятся.</p>${g.members.map(id=>{let s=students.find(s=>s.id===id),present=attendance[k+'_'+id]!==false;return `<div class="person"><div class="info"><strong>${esc(s.name)}</strong><div class="meta">${s.hours} ч на балансе</div><label class="check attendance"><input type="checkbox" role="switch" ${sessionStatus(g,d)==='completed'?'disabled':''} ${present?'checked':''} onchange="setPresence(${g.id},'${d}',${id},this.checked,this)"><span class="switch-track" aria-hidden="true"></span><span class="presence-label">${present?'Присутствует':'Отсутствует'}</span></label></div></div>`}).join('')}<div class="actions"><button ${canCancel(g,d)?'':'disabled'} onclick="cancelSession(${id},'${d}')">Отменить занятие</button><button onclick="closeModal();render()" class="primary">Готово</button></div>${canCancel(g,d)?'':'<p class="meta" style="margin-top:14px">Отмена доступна только более чем за 24 часа до начала.</p>'}`)}
function reschedule(id,d){let g=groups.find(g=>g.id===id);modal(`<h2>Перенос времени</h2><form class="fields" onsubmit="event.preventDefault();overrides['${id}_${d}']={...overrides['${id}_${d}'],time:this.time.value};closeModal();render();toast('Время тренировки изменено')"><label>Новое время<input name="time" type="time" value="${overrides[sk(g,d)]?.time||g.time}" required></label><div class="actions"><button class="primary">Сохранить</button><button type="button" onclick="closeModal()">Отмена</button></div></form>`)}
let notificationQueue=[];
function cancelSession(id,d){let g=groups.find(g=>g.id===id);if(!canCancel(g,d))return toast('До тренировки осталось 24 часа или меньше — отмена недоступна');modal(`<h2>Отменить занятие</h2><p>${esc(g.name)} · ${fmt(d)}. Часы у учеников не снимутся.</p><form class="fields" onsubmit="event.preventDefault();confirmCancellation(${id},'${d}',this.reason.value)"><label>Причина отмены<textarea name="reason" required maxlength="500" placeholder="Например, корт закрыт из-за погоды"></textarea></label><p class="meta">Причина будет включена в уведомление всем участникам.</p><div class="actions"><button class="primary">Подтвердить отмену</button><button type="button" onclick="closeModal()">Назад</button></div></form>`)}
function confirmCancellation(id,d,reason){let g=groups.find(g=>g.id===id);if(!canCancel(g,d))return toast('Отмена уже недоступна');reason=reason.trim();if(!reason)return toast('Укажите причину отмены');if(reason.length>500)return toast('Причина должна быть не длиннее 500 символов');const time=overrides[sk(g,d)]?.time||g.time;overrides[sk(g,d)]={...overrides[sk(g,d)],cancel:true,reason};const text=`Тренировка «${g.name}» ${fmt(d)} в ${time} отменена тренером. Причина: ${reason}. Часы за эту тренировку не снимутся.`;g.members.forEach(studentId=>notificationQueue.push({studentId,text,status:'demo'}));render();modal(`<h2>Тренировка отменена</h2><p>Часы у всех участников сохранятся.</p><h3>Уведомление ученикам</h3><div class="notification-preview">${esc(text)}</div><p class="meta">Предпросмотр для ${g.members.length} участников. Отправка в Telegram пока не подключена.</p><button class="primary" onclick="closeModal()">Готово</button>`)}
function cancelParticipation(id,d){let g=groups.find(g=>g.id===id);if(new Date(d+'T'+(overrides[sk(g,d)]?.time||g.time))-Date.now()<86400000)return;absent[sk(g,d)+'_1']=true;attendance[sk(g,d)+'_1']=false;render();toast('Участие отменено. Час не будет списан')}
function studentView(){if(page==='profile')return heading('Профиль')+`<div class="card"><h2>${role==='parent'?'Айгуль Садыкова':'Алихан Садыков'}</h2><p>Астана · ${role==='parent'?'Родитель Алихана Садыкова':'Ученик'}</p><label>Телефон · необязательно<input type="tel" placeholder="+7"></label><label style="margin-top:20px">Комментарий тренеру<textarea maxlength="500" onchange="students[0].comment=this.value;toast('Комментарий сохранён')" placeholder="В какой группе занимаетесь, дни и время">${esc(students[0].comment||'')}</textarea></label><p style="margin-top:20px">Это пример зарегистрированного аккаунта. Регистрация через Telegram появится после прототипа.</p></div>`;if(page==='trainers')return heading('Тренеры','Астана')+`<label>Поиск по имени<input placeholder="Имя тренера" oninput="document.getElementById('trainerCard').hidden=!profile.name.toLowerCase().includes(this.value.toLowerCase())"></label><div id="trainerCard" class="card" style="margin-top:20px"><span class="badge">Ваш тренер</span><h2>${esc(profile.name)}</h2><p>${esc(profile.place)}</p><p>${esc(profile.bio)}</p><button onclick="toast('В рабочей версии здесь откроется Telegram тренера')">Написать в Telegram</button></div>`;let upcoming=[];for(let i=0;i<14;i++){let d=new Date(day);d.setDate(d.getDate()+i);let date=key(d);sessions(date).filter(g=>g.members.includes(1)).forEach(g=>upcoming.push({g,date}))}return heading(role==='parent'?'Занятия Алихана':'Мои тренировки',`${esc(profile.name)} · Ваш тренер`)+`<div class="card hero-balance"><span>Осталось на балансе</span><strong>${students[0].hours} часа</strong><p>Для пополнения свяжитесь с тренером</p><button class="primary" onclick="toast('В рабочей версии здесь откроется Telegram тренера')">Написать тренеру</button></div><h2>Ближайшие тренировки</h2>${upcoming.slice(0,4).map(({g,date})=>`<p style="margin-top:24px;margin-bottom:8px">${fmt(date)}</p>${sessionCard(g,date,true)}`).join('')||'<div class="empty">Тренировок пока нет</div>'}`}
restoreDemoState();
[profile,...groups].forEach(item=>{const city=cities.find(c=>c.name===item.city);if(city){item.cityId=city.id;item.cityCode=city.code}});
$('#theme').onclick=()=>document.body.classList.toggle('dark');$('#role').onchange=e=>{role=e.target.value;page='home';detail=null;render()};render();
if(document.modelContext?.registerTool){
const tool={name:'read_topcoach_demo',description:'Read local demo groups and balances',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({groups,students})};
try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}
}

setInterval(()=>{settleSessions();saveDemoState();if(page==='home'&&!$('#modal').open)render()},1000);

function closeGroupMenus(){document.querySelectorAll('.group-menu[open]').forEach(menu=>menu.open=false)}
function renameGroup(id){const g=groups.find(g=>g.id===id);if(!g)return;closeGroupMenus();modal(`<h2>Переименовать группу</h2><form class="fields" onsubmit="event.preventDefault();saveGroupName(${id},this.elements.groupName.value)"><label>Название<input name="groupName" value="${esc(g.name)}" required maxlength="60" autofocus></label><div class="actions"><button class="primary">Сохранить</button><button type="button" onclick="closeModal()">Отмена</button></div></form>`)}
function saveGroupName(id,name){const g=groups.find(g=>g.id===id);if(!g)return;name=name.trim();if(!name||name.length>60)return toast('Введите название от 1 до 60 символов');g.name=name;closeModal();render();toast('Группа переименована')}
function askDeleteGroup(id){const g=groups.find(g=>g.id===id);if(!g)return;closeGroupMenus();modal(`<h2>Удалить группу «${esc(g.name)}»?</h2><p>Группа и её тренировки исчезнут из расписания. Ученики и остатки часов сохранятся — учеников можно будет добавить в другую группу.</p><div class="actions"><button class="danger-button" onclick="deleteGroup(${id})">Удалить группу</button><button onclick="closeModal()">Отмена</button></div>`)}
function deleteGroup(id){if(!groups.some(g=>g.id===id))return;groups=groups.filter(g=>g.id!==id);if(detail===id)detail=null;closeModal();render();toast('Группа удалена. Ученики и часы сохранены')}
document.addEventListener('click',event=>{if(!event.target.closest('.group-menu'))closeGroupMenus()});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeGroupMenus()});

function groupTabs(){return `<div class="tabs"><button class="${groupTab==='groups'?'active':''}" onclick="groupTab='groups';detail=null;render()">Группы</button><button class="${groupTab==='students'?'active':''}" onclick="groupTab='students';detail=null;render()">Ученики · ${students.length}</button></div>`}
function filterCards(query,selector){const q=query.trim().toLocaleLowerCase('ru');let count=0;document.querySelectorAll(selector).forEach(card=>{card.hidden=!card.textContent.toLocaleLowerCase('ru').includes(q);if(!card.hidden)count++});const empty=document.getElementById('searchEmpty');if(empty)empty.hidden=count!==0}
function studentsView(){return heading('Мои ученики','Одобренные заявки, группы и баланс часов')+groupTabs()+`<label class="list-search">Поиск учеников<input type="search" placeholder="Фамилия, имя или группа" oninput="filterCards(this.value,'.student-card')"></label><div class="cards">${[...students].sort((a,b)=>(b.hours===0)-(a.hours===0)).map(s=>{const g=groups.find(g=>g.members.includes(s.id));return `<div class="card student-card ${s.hours===0?'zero-hours':''}"><div class="row"><h3>${esc(s.name)}</h3><strong class="balance ${s.hours<1?'low':''}">${s.hours} ч</strong></div><span class="badge">${g?esc(g.name):'Без группы'}</span>${commentInfo(s)}${s.hours===0?'<p class="renewal-note">Часы закончились. Уточните, продолжает ли ученик занятия, затем примите оплату и добавьте часы.</p>':''}<div class="actions"><button class="primary" onclick="editHours(${s.id})">+ Часы и оплата</button>${g?`<button onclick="detail=${g.id};groupTab='groups';render()">Открыть группу</button>`:`<button onclick="chooseStudentGroup(${s.id})">Добавить в группу</button>`}<button onclick="editCoachComment(${s.id})">Комментарий</button></div></div>`}).join('')}</div><p id="searchEmpty" class="empty" ${students.length?'hidden':''}>Ученики не найдены. Сначала примите заявку.</p>`}
function editCoachComment(id){const s=students.find(s=>s.id===id);modal(`<h2>Комментарий тренера</h2><p>${esc(s.name)}</p><form class="fields" onsubmit="event.preventDefault();students.find(s=>s.id===${id}).coachComment=this.note.value.trim();closeModal();render()"><label>Группа, дни и время<textarea name="note" maxlength="500">${esc(s.coachComment??s.comment??'')}</textarea></label><div class="actions"><button class="primary">Сохранить</button><button type="button" onclick="closeModal()">Отмена</button></div></form>`)}
function chooseStudentGroup(id){const s=students.find(s=>s.id===id);if(!s||!available().some(s=>s.id===id))return;const eligible=groups.filter(g=>g.type==='Групповая'||!g.members.length);modal(`<h2>Добавить в группу</h2><p>${esc(s.name)}</p>${commentInfo(s)}<div class="fields">${eligible.map(g=>`<button onclick="assignStudent(${id},${g.id})"><strong>${esc(g.name)}</strong><div class="meta">${esc(g.type)} · ${g.time} · ${esc(g.place)}</div></button>`).join('')||'<p>Подходящих групп пока нет. Сначала создайте группу.</p>'}</div><button class="ghost" onclick="closeModal()">Отмена</button>`)}
function assignStudent(studentId,groupId){settleSessions();const g=groups.find(g=>g.id===groupId);if(!g||!available().some(s=>s.id===studentId)||(g.type==='Индивидуальная'&&g.members.length))return toast('Добавление недоступно');g.members.push(studentId);closeModal();render();toast('Ученик добавлен в группу')}
function premiumExport(){modal(`<span class="badge">TOPCOACH PREMIUM</span><h2>Выгрузка отчётов — в Premium</h2><p>Скачивайте заявки и отчёты для работы вне приложения.</p><div class="actions"><button class="primary" onclick="closeModal();page='subscription';render()">Подробнее</button><button onclick="closeModal()">Закрыть</button></div>`)}
function subscriptionView(){return `<button class="ghost" onclick="page='requests';render()">← К заявкам</button><section class="premium-hero"><span class="premium-eyebrow">TOPCOACH PREMIUM</span><h1>Больше времени<br>для игры.</h1><p>Развивайте тренерскую практику: создавайте больше групп и получайте отчёты, которые удобно сохранить и сравнить.</p><div class="premium-tags"><span>Больше групп</span><span>Выгрузка отчётов</span><span>Подробная аналитика</span></div></section><div class="plans"><section class="card plan"><span class="badge">ДЛЯ СТАРТА</span><h2>Бесплатно</h2><div class="plan-price">0 ₸</div><p>Всё для ежедневной работы с учениками.</p><ul><li>До 5 групп, включая индивидуальные</li><li>Заявки и список учеников</li><li>Расписание и посещаемость</li><li>Начисление часов и учёт оплат</li><li>Базовая выручка за период</li><li>Уведомления о занятиях и отменах</li></ul><span class="badge">Ваш текущий план</span></section><section class="card plan premium-plan"><span class="badge">ДЛЯ РОСТА</span><h2>Premium</h2><div class="plan-price">Больше возможностей</div><p>Для тренеров с большим числом групп.</p><ul><li>Всё из бесплатного плана</li><li>Более 5 групп</li><li>Выгрузка заявок</li><li>Выгрузка отчётов по группам и оплатам</li><li>Подробная аналитика по группам и типам занятий</li></ul><button class="primary" onclick="toast('Подписка пока не подключена. Стоимость объявим перед запуском')">Скоро доступно</button><small>Стоимость определим перед запуском</small></section></div><p class="subscription-note">Предварительное разделение тарифов для MVP. Оплата подписки и выгрузки пока не подключены; Telegram-уведомления появятся после подключения бота.</p>`}

function sessionStatus(g,d){const start=sessionStart(g,d),now=Date.now();return now>=start+3600000?'completed':now>=start?'live':'upcoming'}
function settleSessions(){const now=Date.now();let date=new Date(lifecycleSince);date.setHours(0,0,0,0);for(;date.getTime()<=now;date.setDate(date.getDate()+1)){const d=key(date);for(const g of sessions(d)){const end=sessionStart(g,d)+3600000,k=sk(g,d);if(end<=lifecycleSince||end>now||completedSessions[k])continue;const records=g.members.map(id=>{const s=students.find(s=>s.id===id),present=attendance[k+'_'+id]!==false&&!absent[k+'_'+id];const charged=s&&present&&s.hours>=1?1:0;if(charged)s.hours--;log.unshift({id,sessionKey:k,text:`${d} · ${g.name} · ${charged?'-1 ч':present?'Без списания: нет часов':'Отсутствовал — без списания'}`,recordedAt:new Date().toISOString()});return {studentId:id,present,charged}});completedSessions[k]={groupId:g.id,groupName:g.name,date:d,endedAt:new Date(end).toISOString(),records}}}}
